#include <stdio.h>

typedef struct { int num; char name[32]; double score; } Student;

int main(void) {
    int n;
    Student a[100];
    scanf("%d", &n);
    for (int i = 0; i < n; i++) scanf("%d%31s%lf", &a[i].num, a[i].name, &a[i].score);
    for (int i = 0; i < n - 1; i++) for (int j = i + 1; j < n; j++)
        if (a[i].score < a[j].score || (a[i].score == a[j].score && a[i].num > a[j].num)) {
            Student temp = a[i]; a[i] = a[j]; a[j] = temp;
        }
    for (int i = 0; i < n; i++) printf("%d %s %.2f\n", a[i].num, a[i].name, a[i].score);
    return 0;
}
